@page "/chat"
@using sv_d904904ae6da43f78b5e1cabd267e2c1.Models
@namespace sv_d904904ae6da43f78b5e1cabd267e2c1.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="message-area @(_threadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <div class="area-header">
                <h5># @_activeChannel.Name</h5>
                <p>@_activeChannel.Description</p>
            </div>

            <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages...</div>
                }
                @foreach (var msg in _messages)
                {
                    <MessageBubble Message="msg"
                                   ThreadReplyCount="GetThreadReplyCount(msg.Id)"
                                   OnOpenThread="OpenThread"
                                   OnReact="HandleReaction" />
                }
            </div>

            <MessageInput Placeholder="@($"Message #{_activeChannel.Name}")"
                          ButtonLabel="Send"
                          OnSend="SendMessage" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel>? _channels;
    private List<Message> _messages = new();
    private List<Message>? _threadReplies;
    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    private Channel? _activeChannel;
    private int _activeChannelId;
    private Message? _threadRootMessage;
    private bool _threadOpen;
    private bool _loadingMore;
    private bool _allLoaded;
    private const int PageSize = 30;
    private ElementReference _messageListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels?.FirstOrDefault(c => c.Id == channelId);
        _messages = new();
        _allLoaded = false;
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = null;
        _threadSummaries = new();

        var msgs = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = msgs;
        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update the channel's unread count locally
        if (_channels is not null)
        {
            var idx = _channels.FindIndex(c => c.Id == channelId);
            if (idx >= 0)
            {
                _channels[idx] = _channels[idx] with { UnreadCount = 0 };
            }
        }
    }

    private async Task HandleScroll()
    {
        // The scroll-to-top detection is approximate in Blazor Server;
        // a JS interop call would be more precise. Here we provide a
        // "Load older" affordance at the top of the list.
    }

    private async Task LoadOlderMessages()
    {
        if (_loadingMore || _allLoaded || _activeChannel is null) return;
        _loadingMore = true;

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count < PageSize)
        {
            _allLoaded = true;
        }
        _messages.InsertRange(0, older);
        BuildThreadSummaries();
        _loadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = null;
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies?.Add(reply);

        // Update thread summary
        if (_threadSummaries.ContainsKey(_threadRootMessage.Id))
        {
            var s = _threadSummaries[_threadRootMessage.Id];
            _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(s.RootMessageId, s.ReplyCount + 1, DateTime.UtcNow);
        }
        else
        {
            _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(_threadRootMessage.Id, 1, DateTime.UtcNow);
        }
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        var idx = _messages.FindIndex(m => m.Id == args.MessageId);
        if (idx >= 0)
        {
            var msg = _messages[idx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                if (!r.Users.Contains("You"))
                {
                    reactions[existing] = new Reaction(r.Emoji, [..r.Users, "You"]);
                }
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            _messages[idx] = msg with { Reactions = reactions };
        }
    }

    private void BuildThreadSummaries()
    {
        _threadSummaries.Clear();
        var replies = _messages.Where(m => m.ReplyToId.HasValue).GroupBy(m => m.ReplyToId!.Value);
        foreach (var group in replies)
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }

    private int GetThreadReplyCount(int messageId) =>
        _threadSummaries.TryGetValue(messageId, out var summary) ? summary.ReplyCount : 0;
}

